-- Draft HR and asset maintenance; depends on 001 and 003.
begin;
create table erp.employees(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, user_id uuid unique references auth.users, hired_on date, active boolean not null default true);
create table erp.departments(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null);
create table erp.employment_terms(id uuid primary key default gen_random_uuid(), employee_id uuid not null references erp.employees, department_id uuid references erp.departments, effective_from date not null, effective_to date, base_salary numeric(24,8) not null check(base_salary>=0), check(effective_to is null or effective_to>=effective_from), unique(employee_id,effective_from));
create table erp.attendance(id uuid primary key default gen_random_uuid(), employee_id uuid not null references erp.employees, clock_in timestamptz not null, clock_out timestamptz, check(clock_out is null or clock_out>clock_in));
create table erp.leave_requests(id uuid primary key default gen_random_uuid(), employee_id uuid not null references erp.employees, starts_on date not null, ends_on date not null, kind text not null, status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')), check(ends_on>=starts_on));
create table erp.payroll_runs(id uuid primary key default gen_random_uuid(), period_id uuid not null references erp.fiscal_periods, status text not null default 'draft' check(status in ('draft','approved','posted')), journal_entry_id uuid unique references erp.journal_entries);
create table erp.payroll_lines(id uuid primary key default gen_random_uuid(), run_id uuid not null references erp.payroll_runs, employee_id uuid not null references erp.employees, component text not null, kind text not null check(kind in ('earning','deduction','employer_cost')), amount numeric(24,8) not null check(amount>=0));
create table erp.assets(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, location_id uuid references erp.locations, acquired_on date not null, acquisition_cost numeric(24,8) not null check(acquisition_cost>=0), residual_value numeric(24,8) not null default 0 check(residual_value>=0 and residual_value<=acquisition_cost), useful_life_months integer not null check(useful_life_months>0), asset_account_id uuid references erp.accounts, depreciation_account_id uuid references erp.accounts, accumulated_depreciation_account_id uuid references erp.accounts, status text not null default 'active' check(status in ('active','retired','disposed')));
create table erp.depreciation_entries(asset_id uuid references erp.assets, period_id uuid references erp.fiscal_periods, amount numeric(24,8) not null check(amount>=0), journal_entry_id uuid references erp.journal_entries, primary key(asset_id,period_id));
create table erp.maintenance_plans(id uuid primary key default gen_random_uuid(), asset_id uuid not null references erp.assets, description text not null, interval_days integer not null check(interval_days>0), next_due date not null, active boolean not null default true);
create table erp.maintenance_orders(id uuid primary key default gen_random_uuid(), asset_id uuid not null references erp.assets, plan_id uuid references erp.maintenance_plans, kind text not null check(kind in ('preventive','corrective')), status text not null default 'open' check(status in ('open','running','completed','cancelled')), opened_at timestamptz not null default now(), completed_at timestamptz, notes text);
create table erp.maintenance_costs(id uuid primary key default gen_random_uuid(), order_id uuid not null references erp.maintenance_orders, amount numeric(24,8) not null check(amount>=0), journal_line_id bigint unique references erp.journal_lines);
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Payroll statutory rules, privacy, asset depreciation limits and maintenance posting remain pending.
